/* Keep interactive compare and share within the same section; no overlap. */
#yourResult .result-layout{display:grid;grid-template-columns:minmax(0,2.3fr) minmax(230px,.74fr);gap:10px;align-items:stretch}
#yourResult .result-layout .result-pair{margin-right:0!important;min-width:0;align-items:stretch}
#yourResult .result-layout .share-aside{position:static!important;width:auto!important;margin:0!important;max-height:none!important}
#yourResult .result-layout .distbox{min-width:0}
@media(max-width:750px){#yourResult .result-layout{grid-template-columns:1fr}#yourResult .result-layout .result-pair{grid-template-columns:1fr 1fr}.share-aside .share-tools{grid-template-columns:1fr 1fr}}
